select
u.*,
GROUP_CONCAT(distinct r.role_name separator ',') as role_name,
GROUP_CONCAT(distinct d.dept_name separator ',') as dept_name
from sys_user u
left join sys_user_role sur on u.id = sur.user_id

    AND sur.role_id = #{roleId}

left join sys_role r on sur.role_id = r.id
left join sys_user_dept sud on u.id = sud.user_id

    AND sud.dept_id = #{deptId}

left join sys_dept d on sud.dept_id = d.id


        and u.id=#{id}


        and u.phone=#{phone}


        AND u.user_name = #{userName}


group by u.id

select
    u.*,
    GROUP_CONCAT(distinct r.role_name separator ',') as role_name,
    GROUP_CONCAT(distinct d.dept_name separator ',') as dept_name
from sys_user u
    left join sys_user_role sur on u.id = sur.user_id

        AND sur.role_id = #{params.roleId}

    left join sys_role r on sur.role_id = r.id
    left join sys_user_dept sud on u.id = sud.user_id

        AND sud.dept_id = #{params.deptId}

    left join sys_dept d on sud.dept_id = d.id


        AND u.user_name like concat('%', #{params.userName}, '%')


        AND u.real_name like concat('%', #{params.realName}, '%')


        AND u.phone like concat('%', #{params.phone}, '%')


        AND u.state = #{params.state}


        AND u.create_time >= #{params.beginTime}


        AND u.create_time <= #{params.endTime}


        AND u.id=#{params.parentId}


group by u.id
ORDER BY u.create_time desc

select
    u.*,
    GROUP_CONCAT(distinct r.role_name separator ',') as role_name,
    GROUP_CONCAT(distinct d.dept_name separator ',') as dept_name
from sys_user u
    left join sys_user_role sur on u.id = sur.user_id

        AND sur.role_id = #{params.roleId}

    left join sys_role r on sur.role_id = r.id
    left join sys_user_dept sud on u.id = sud.user_id

        AND sud.dept_id = #{params.deptId}

    left join sys_dept d on sud.dept_id = d.id


        AND u.id = #{params.id}


        AND u.user_name like concat('%', #{params.userName}, '%')


        AND u.real_name like concat('%', #{params.realName}, '%')


        AND u.phone like concat('%', #{params.phone}, '%')


        AND u.state = #{params.state}


        AND u.create_time >= #{params.beginTime}


        AND u.create_time <= #{params.endTime}


group by u.id
ORDER BY u.create_time desc

    limit #{params.maxRows}
